{
  "commonPhenomenon": "平台在订单已关单（close）后，收到支付通道返回的成功回调（paid），导致本地终态与通道状态冲突。",
  "facts": [
    {
      "statement": "异常类型为 PAYMENT_STATE，具体表现为 close_paid，即平台已关单后收到通道成功回调。",
      "evidenceIds": [
        "E-02-1"
      ]
    },
    {
      "statement": "回调处理记录显示支付成功，但本地支付终态为关闭。",
      "evidenceIds": [
        "E-02-2"
      ]
    },
    {
      "statement": "同类订单出现关单后迟到成功的情况，且人工处置状态待核实。",
      "evidenceIds": [
        "E-02-3"
      ]
    }
  ],
  "differences": [],
  "possibleExplanations": [
    {
      "hypothesis": "通道侧存在网络延迟或异步处理滞后，导致成功通知晚于平台关单动作到达。",
      "evidenceIds": [
        "E-02-1",
        "E-02-2"
      ],
      "verification": "需通过可信只读查单确认通道实际扣款/成功时间戳，并比对通道交易号与平台关单请求的时间序列。"
    },
    {
      "hypothesis": "平台与通道的状态映射逻辑或时区处理存在差异，导致对同一交易状态的判断出现偏差。",
      "evidenceIds": [
        "E-02-2",
        "E-02-3"
      ],
      "verification": "需检查回调数据中的时间戳时区、通道状态码到平台状态的映射规则，以及是否存在旧快照导致的表面冲突。"
    },
    {
      "hypothesis": "通道侧在平台发起关单前已完成支付，但因并发竞争条件导致平台误判为可关单。",
      "evidenceIds": [
        "E-02-1"
      ],
      "verification": "需获取通道侧关于该笔交易的完整操作审计日志，确认支付完成时间与关单请求时间的先后关系。"
    }
  ],
  "checkSteps": [
    "核对商户订单号、通道交易号和商户号是否指向同一笔交易。",
    "比较平台关单请求时间、通道关单应答时间、通道实际支付时间及通知生成时间。",
    "检查时间戳时区一致性，排除因时区转换错误导致的时序误判。",
    "通过可信只读接口进行查单，确认当前资金结果及通道真实状态。",
    "交由有权限的人员按业务流程复核后续处理，不自动改写状态。"
  ],
  "missingInformation": [
    "通道侧具体的成功时间戳和关单应答时间戳。",
    "平台发起关单的具体时间点及对应的通道交互记录。",
    "回调数据中携带的原始通道状态码及映射后的内部状态详情。"
  ],
  "knowledgeCitations": [
    "late-success-after-close",
    "terminal-conflict"
  ],
  "knowledgeOmissionReason": ""
}
